namespace HybridCPU_ISE.Tests.Architecture;
public sealed class Rf129atReplayTokenInvalidBehaviorDecisionTests
{[Fact] public void PaperKeepsReplayBoundaryFailClosed(){string p=File.ReadAllText(Path.Combine(Root(),"ResearchPaper","section","md base","3_Architectural_Overview_and_Frontend_Contract.md"));Assert.Contains("Unbound, malformed or boundary-invalid `ReplayToken`",p,StringComparison.Ordinal);Assert.Contains("partial, zero-filled or substituted memory image",p,StringComparison.Ordinal);Assert.Contains("materialize a timed-memory request or fallback binding",p,StringComparison.Ordinal);Assert.Contains("No shared invalid result",p,StringComparison.Ordinal);}private static string Root(){DirectoryInfo? c=new(AppContext.BaseDirectory);while(c is not null){if(Directory.Exists(Path.Combine(c.FullName,"ResearchPaper")))return c.FullName;c=c.Parent;}throw new DirectoryNotFoundException();}}
